// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{})
}

type ChiServerOptions struct {
	BaseURL          string
	BaseRouter       chi.Router
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, r chi.Router) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseRouter: r,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, r chi.Router, baseURL string) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseURL:    baseURL,
		BaseRouter: r,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options ChiServerOptions) http.Handler {
	r := options.BaseRouter

	if r == nil {
		r = chi.NewRouter()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/callbacks/ci-rebuild", wrapper.RecordCIRebuildCallback)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/previews", wrapper.PreviewPublication)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/publications", wrapper.ListPublications)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/publications", wrapper.CreatePublication)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/publications/{id}", wrapper.GetPublication)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/publishable-positions", wrapper.GetPublishableQueue)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/rebuild-requests/{intent_id}/settle", wrapper.SettleRebuildRequest)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/releases/{id}/rebuild-cycle", wrapper.GetReleaseRebuildCycle)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/releases/{id}/rebuild-cycle/request-again", wrapper.RequestRebuildAgain)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/releases/{id}/rebuild-cycle/stop", wrapper.StopRebuildCycle)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/releases/{id}/rollup-status", wrapper.GetRollupStatus)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/reports/remediation-metrics", wrapper.GetRemediationMetricsReport)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/rollups", wrapper.ListRollups)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/rollups/{id}", wrapper.GetRollup)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/webhook-health", wrapper.GetWebhookHealth)
	})

	return r
}

